   289	/** Get the private pusher channel name for a Report. */
   290	function getReportChannelName(reportID: string): string {
   291	    return `${CONST.PUSHER.PRIVATE_REPORT_CHANNEL_PREFIX}${reportID}${CONFIG.PUSHER.SUFFIX}`;
   292	}
   293	
   294	/**
   295	 * There are 2 possibilities that we can receive via pusher for a user's typing/leaving status:
   296	 * 1. The "new" way from New Expensify is passed as {[login]: Boolean} (e.g. {yuwen@expensify.com: true}), where the value
   297	 * is whether the user with that login is typing/leaving on the report or not.
   298	 * 2. The "old" way from e.com which is passed as {userLogin: login} (e.g. {userLogin: bstites@expensify.com})
   299	 *
   300	 * This method makes sure that no matter which we get, we return the "new" format
   301	 */
   302	function getNormalizedStatus(typingStatus: Pusher.UserIsTypingEvent | Pusher.UserIsLeavingRoomEvent): ReportUserIsTyping {
   303	    let normalizedStatus: ReportUserIsTyping;
   304	
   305	    if (typingStatus.userLogin) {
   306	        normalizedStatus = {[typingStatus.userLogin]: true};
   307	    } else {
   308	        normalizedStatus = typingStatus;
   309	    }
   310	
   311	    return normalizedStatus;
   312	}
   313	
   314	/** Initialize our pusher subscriptions to listen for someone typing in a report. */
   315	function subscribeToReportTypingEvents(reportID: string) {
   316	    if (!reportID) {
   317	        return;
   318	    }
   319	
   320	    // Make sure we have a clean Typing indicator before subscribing to typing events
   321	    Onyx.set(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, {});
   322	
   323	    const pusherChannelName = getReportChannelName(reportID);
   324	    Pusher.subscribe(pusherChannelName, Pusher.TYPE.USER_IS_TYPING, (typingStatus) => {
   325	        // If the pusher message comes from OldDot, we expect the typing status to be keyed by user
   326	        // login OR by 'Concierge'. If the pusher message comes from NewDot, it is keyed by accountID
   327	        // since personal details are keyed by accountID.
   328	        const normalizedTypingStatus = getNormalizedStatus(typingStatus);
   329	        const accountIDOrLogin = Object.keys(normalizedTypingStatus)[0];
   330	
   331	        if (!accountIDOrLogin) {
   332	            return;
   333	        }
   334	
   335	        // Don't show the typing indicator if the user is typing on another platform
   336	        if (Number(accountIDOrLogin) === currentUserAccountID) {
   337	            return;
   338	        }
   339	
   340	        // Use a combo of the reportID and the accountID or login as a key for holding our timers.
   341	        const reportUserIdentifier = `${reportID}-${accountIDOrLogin}`;
   342	        clearTimeout(typingWatchTimers[reportUserIdentifier]);
   343	        Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, normalizedTypingStatus);
   344	
   345	        // Wait for 1.5s of no additional typing events before setting the status back to false.
   346	        typingWatchTimers[reportUserIdentifier] = setTimeout(() => {
   347	            const typingStoppedStatus: ReportUserIsTyping = {};
   348	            typingStoppedStatus[accountIDOrLogin] = false;
   349	            Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, typingStoppedStatus);
   350	            delete typingWatchTimers[reportUserIdentifier];
   351	        }, 1500);
   352	    }).catch((error: ReportError) => {
   353	        Log.hmmm('[Report] Failed to initially subscribe to Pusher channel', {errorType: error.type, pusherChannelName});
   354	    });
   355	}
